55, 0.72); --site-footer-head: #fff; --site-footer-top: none; --site-eyebrow: var(--site-muted); --site-hero-bg: var(--site-surface); --site-frame-pad: 0; --site-frame-bg: transparent; --site-frame-border: none; --site-eyebrow-bg: transparent; --site-eyebrow-pad: 0; --site-head-rule: none; --site-head-pad: 0; --site-value-ink: var(--site-ink); --site-keys-border: var(--site-rule); --site-card-edge: none; --site-badge-edge: none; --site-panel-edge: none; --site-step-top: none; --site-list-marker: 0; --site-catalog-row: minmax(0, 11em) minmax(0, 1fr); --site-spec-table-border: var(--site-rule); --site-spec-table-head: transparent; --site-panel-bg: var(--site-tint); --site-panel-copy-bg: transparent; --site-form-card: var(--site-surface); --site-group-columns: minmax(0, 12em) minmax(0, 1fr); --site-rule: 1px solid var(--site-line); --site-rule-strong: 2px solid var(--site-ink);}
*{box-sizing: border-box;}
html{background: var(--site-bg); color: var(--site-ink); font-family: var(--site-font); overflow-x: hidden; -webkit-font-smoothing: antialiased; scroll-behavior: smooth;}
